LESSONS8[1] = {"guide": "lucia", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Un billete para Toledo, por favor", "m": ["a ticket to Toledo, please", "톨레도행 표 한 장 주세요"]}, {"w": "¿Ida o ida y vuelta?", "m": ["one way or return?", "편도요, 왕복이요?"]}, {"w": "Ida y vuelta", "m": ["return", "왕복이요"]}, {"w": "¿De qué andén sale?", "m": ["which platform does it leave from?", "몇 번 승강장에서 출발해요?"]}, {"w": "¿A qué hora sale el próximo tren?", "m": ["what time does the next train leave?", "다음 기차는 몇 시에 출발해요?"]}, {"w": "Sale de la vía cinco", "m": ["it leaves from track five", "5번 선로에서 출발해요"]}], "intro": ["Welcome to the train trips. Your Camino is done, and Spain is waiting. In Madrid you will buy a train ticket and find your platform.", "기차 여행에 온 걸 환영해요. 순례길은 끝났고, 스페인이 기다리고 있어요. 마드리드에서는 기차표를 사고 승강장을 찾아봐요."], "tip": ["Spain's trains are run mostly by Renfe, along with a few newer companies. Un billete is a ticket. Ida is one way, ida y vuelta is return. Andén is the platform and vía is the track; boards show both. Madrid has two big stations, Atocha in the south and Chamartín in the north, so check which one your train uses.", "스페인 기차는 주로 렌페(Renfe)가 운행하고, 새로 생긴 회사도 몇 곳 있어요. billete는 \"표\"예요. ida는 편도, ida y vuelta는 왕복이에요. andén은 승강장, vía는 선로이고, 전광판에 둘 다 나와요. 마드리드에는 남쪽 아토차와 북쪽 차마르틴, 큰 역이 두 개 있으니 내 기차가 어느 역인지 확인해요."], "choose": [{"say": "Un billete para Toledo, por favor", "opts": [["a ticket to Toledo, please", "톨레도행 표 한 장 주세요"], ["a map of Toledo, please", "톨레도 지도 주세요"], ["a seat in Toledo, please", "톨레도에서 자리 하나 주세요"]], "ans": 0, "why": ["Billete: ticket.", "billete는 \"표\"예요."]}, {"say": "¿Ida o ida y vuelta?", "opts": [["one way or return?", "편도요, 왕복이요?"], ["are you going or staying?", "가세요, 머무세요?"], ["today or tomorrow?", "오늘이요, 내일이요?"]], "ans": 0, "why": ["Ida: going. Vuelta: coming back.", "ida는 \"가는 것\", vuelta는 \"돌아오는 것\"이에요."]}, {"say": "¿De qué andén sale?", "opts": [["which platform does it leave from?", "몇 번 승강장에서 출발해요?"], ["what time does it leave?", "몇 시에 출발해요?"], ["where does it arrive?", "어디에 도착해요?"]], "ans": 0, "why": ["Andén: platform.", "andén은 \"승강장\"이에요."]}, {"say": "¿A qué hora sale el próximo tren?", "opts": [["what time does the next train leave?", "다음 기차는 몇 시에 출발해요?"], ["what time did the last train leave?", "마지막 기차는 몇 시에 떠났어요?"], ["how long is the train ride?", "기차로 얼마나 걸려요?"]], "ans": 0, "why": ["Próximo: next.", "próximo는 \"다음\"이에요."]}, {"say": "Sale de la vía cinco", "opts": [["it leaves from track five", "5번 선로에서 출발해요"], ["it leaves at five", "다섯 시에 출발해요"], ["it takes five minutes", "5분 걸려요"]], "ans": 0, "why": ["Vía: track.", "vía는 \"선로\"예요."]}, {"say": "Ida y vuelta", "opts": [["return", "왕복이요"], ["one way", "편도요"], ["turn around", "돌아가세요"]], "ans": 0, "why": ["Return ticket: billete de ida y vuelta.", "왕복표는 billete de ida y vuelta예요."]}], "speak": [{"w": "Un billete para Toledo, por favor", "m": ["a ticket to Toledo, please", "톨레도행 표 한 장 주세요"], "n": ["oon bee-YEH-teh PA-ra to-LEH-do.", "\"운 비예떼 빠라 똘레도\"."]}, {"w": "¿Ida o ida y vuelta?", "m": ["one way or return?", "편도요, 왕복이요?"], "n": ["EE-da o EE-da ee BWEL-ta.", "\"이다 오 이다 이 부엘따\"."]}, {"w": "¿De qué andén sale?", "m": ["which platform does it leave from?", "몇 번 승강장에서 출발해요?"], "n": ["deh keh an-DEN SA-leh.", "\"데 께 안덴 살레\"."]}, {"w": "¿A qué hora sale el próximo tren?", "m": ["what time does the next train leave?", "다음 기차는 몇 시에 출발해요?"], "n": ["a keh O-ra SA-leh el PROK-see-mo tren.", "\"아 께 오라 살레 엘 쁘록시모 뜨렌\"."]}], "build": [{"s": "Dos billetes de ida y vuelta", "m": ["two return tickets", "왕복표 두 장"]}, {"s": "¿De qué vía sale el tren?", "m": ["which track does the train leave from?", "기차는 몇 번 선로에서 출발해요?"]}, {"s": "El próximo tren sale a las diez", "m": ["the next train leaves at ten", "다음 기차는 열 시에 출발해요"]}, {"s": "¿Este tren va a Toledo?", "m": ["does this train go to Toledo?", "이 기차 톨레도 가요?"]}], "note": ["Madrid sits right in the middle of Spain, and its rail lines spread out like the spokes of a wheel. From Atocha, fast trains reach Toledo, Seville, Valencia, and many other cities in a few hours or less.", "마드리드는 스페인 한가운데 있고, 철도는 바퀴살처럼 사방으로 뻗어 있어요. 아토차역에서 고속 열차를 타면 톨레도, 세비야, 발렌시아 같은 많은 도시에 몇 시간 안에 닿아요."], "today": [0, 1, 2]};
LESSONS8[2] = {"guide": "ramon", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¿Qué línea va al Prado?", "m": ["which line goes to the Prado?", "프라도에는 몇 호선이 가요?"]}, {"w": "Tiene que hacer transbordo", "m": ["you have to change lines", "갈아타야 해요"]}, {"w": "¿Cuál es la próxima parada?", "m": ["what is the next stop?", "다음 정류장이 어디예요?"]}, {"w": "Me bajo aquí", "m": ["I get off here", "여기서 내려요"]}, {"w": "¿Dónde está la salida?", "m": ["where is the exit?", "출구가 어디예요?"]}, {"w": "Una tarjeta de transporte, por favor", "m": ["a transport card, please", "교통카드 하나 주세요"]}], "intro": ["Madrid's Metro is big, fast, and easy once you know a few words. Today you will ask which line to take, change trains, and find the way out.", "마드리드 지하철은 크고 빠르고, 몇 마디만 알면 쉬워요. 오늘은 몇 호선을 타는지 묻고, 갈아타고, 나가는 길을 찾아봐요."], "tip": ["Lines are called líneas and have numbers and colors. Hacer transbordo means to change lines. On the platform, the next stop is la próxima parada. To get off, bajarse: me bajo aquí. Getting on is subir. Follow the signs that say salida for the exit. Visitors usually load trips onto a rechargeable transport card.", "노선은 línea라고 하고 번호와 색이 있어요. hacer transbordo는 \"갈아타다\"예요. 다음 정류장은 la próxima parada예요. 내리는 건 bajarse로 me bajo aquí, 타는 건 subir예요. 출구는 salida 표지판을 따라가요. 여행자는 보통 충전식 교통카드에 승차권을 넣어 써요."], "choose": [{"say": "¿Qué línea va al Prado?", "opts": [["which line goes to the Prado?", "프라도에는 몇 호선이 가요?"], ["how long is the line?", "줄이 얼마나 길어요?"], ["is the Prado open?", "프라도 열었어요?"]], "ans": 0, "why": ["Línea: line. Al: a plus el.", "línea는 \"노선\", al은 a와 el이 합쳐진 거예요."]}, {"say": "Tiene que hacer transbordo", "opts": [["you have to change lines", "갈아타야 해요"], ["you have to buy a ticket", "표를 사야 해요"], ["you have to wait", "기다려야 해요"]], "ans": 0, "why": ["Tener que: to have to.", "tener que는 \"~해야 한다\"예요."]}, {"say": "¿Cuál es la próxima parada?", "opts": [["what is the next stop?", "다음 정류장이 어디예요?"], ["where is the bus stop?", "버스 정류장이 어디예요?"], ["what was the last stop?", "지난 정류장이 어디였어요?"]], "ans": 0, "why": ["Parada: stop.", "parada는 \"정류장\"이에요."]}, {"say": "Me bajo aquí", "opts": [["I get off here", "여기서 내려요"], ["I get on here", "여기서 타요"], ["I live here", "여기 살아요"]], "ans": 0, "why": ["Bajarse: to get off. Subir: to get on.", "bajarse는 \"내리다\", subir는 \"타다\"예요."]}, {"say": "¿Dónde está la salida?", "opts": [["where is the exit?", "출구가 어디예요?"], ["where is the entrance?", "입구가 어디예요?"], ["when is the departure?", "출발이 언제예요?"]], "ans": 0, "why": ["Salida: exit, or departure. Entrance: entrada.", "salida는 \"출구\" 또는 \"출발\", 입구는 entrada예요."]}, {"say": "Una tarjeta de transporte, por favor", "opts": [["a transport card, please", "교통카드 하나 주세요"], ["a postcard, please", "엽서 한 장 주세요"], ["a taxi, please", "택시 불러 주세요"]], "ans": 0, "why": ["Transporte: public transport.", "transporte는 \"대중교통\"이에요."]}], "speak": [{"w": "¿Qué línea va al Prado?", "m": ["which line goes to the Prado?", "프라도에는 몇 호선이 가요?"], "n": ["keh LEE-neh-a ba al PRA-do.", "\"께 리네아 바 알 쁘라도\"."]}, {"w": "Tiene que hacer transbordo", "m": ["you have to change lines", "갈아타야 해요"], "n": ["TYEH-neh keh a-THEHR trans-BOR-do.", "\"띠에네 께 아쎄르 뜨란스보르도\"."]}, {"w": "Me bajo aquí", "m": ["I get off here", "여기서 내려요"], "n": ["meh BA-ho a-KEE.", "\"메 바호 아끼\"."]}, {"w": "¿Dónde está la salida?", "m": ["where is the exit?", "출구가 어디예요?"], "n": ["DON-deh es-TA la sa-LEE-da.", "\"돈데 에스따 라 살리다\"."]}], "build": [{"s": "Tiene que coger la línea dos", "m": ["you have to take line two", "2호선을 타야 해요"]}, {"s": "Hago transbordo en Sol", "m": ["I change lines at Sol", "솔역에서 갈아타요"]}, {"s": "Me bajo en la próxima parada", "m": ["I get off at the next stop", "다음 정류장에서 내려요"]}, {"s": "La salida está a la derecha", "m": ["the exit is on the right", "출구는 오른쪽에 있어요"]}], "note": ["The Puerta del Sol, with its famous clock, is the heart of Madrid and the official center of Spain's road network: a plaque on the ground marks kilometer zero. On New Year's Eve, Spaniards eat twelve grapes with the twelve chimes of this clock.", "유명한 시계가 있는 푸에르타 델 솔은 마드리드의 심장이자 스페인 도로망의 공식 중심이에요. 바닥에 0킬로미터 표지판이 있어요. 섣달그믐 밤에 스페인 사람들은 이 시계의 열두 번 종소리에 맞춰 포도 열두 알을 먹어요."], "today": [0, 1, 3]};
LESSONS8[3] = {"guide": "begona", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Dos entradas, por favor", "m": ["two tickets, please", "입장권 두 장 주세요"], "n": ["For museums and shows, a ticket is una entrada.", "박물관이나 공연 표는 entrada라고 해요."]}, {"w": "¿Hay descuento para estudiantes?", "m": ["is there a student discount?", "학생 할인 있어요?"]}, {"w": "¿Se pueden hacer fotos?", "m": ["can you take photos?", "사진 찍어도 돼요?"]}, {"w": "¿Dónde está el guardarropa?", "m": ["where is the cloakroom?", "물품 보관소가 어디예요?"]}, {"w": "¿Hay que hacer cola?", "m": ["do we have to queue?", "줄 서야 해요?"]}, {"w": "Es gratis a partir de las seis", "m": ["it is free from six o'clock", "여섯 시부터 무료예요"]}], "intro": ["Madrid has some of the greatest art museums in the world, all close together along one avenue. Today you will buy tickets and ask the questions every visitor needs.", "마드리드에는 세계적인 미술관들이 한 거리를 따라 가까이 모여 있어요. 오늘은 입장권을 사고, 방문객이라면 꼭 필요한 질문을 해 봐요."], "tip": ["A train ticket is un billete, but a museum or concert ticket is una entrada. Descuento is a discount. ¿Se puede...? asks if something is allowed: ¿se pueden hacer fotos? A cola is a queue, so hacer cola is to stand in line. Big bags often go to the guardarropa, the cloakroom. Many museums have free hours, so ask ¿cuándo es gratis?", "기차표는 billete지만 박물관이나 공연 표는 entrada예요. descuento는 \"할인\"이에요. ¿se puede...?는 해도 되는지 물어요. ¿se pueden hacer fotos? cola는 \"줄\"이라서 hacer cola는 \"줄 서다\"예요. 큰 가방은 보통 guardarropa(물품 보관소)에 맡겨요. 무료 시간이 있는 박물관이 많으니 ¿cuándo es gratis?라고 물어봐요."], "choose": [{"say": "Dos entradas, por favor", "opts": [["two tickets, please", "입장권 두 장 주세요"], ["two entrances, please", "입구 두 개요"], ["two coffees, please", "커피 두 잔 주세요"]], "ans": 0, "why": ["Entrada: entry ticket, also entrance.", "entrada는 \"입장권\"이자 \"입구\"예요."]}, {"say": "¿Hay descuento para estudiantes?", "opts": [["is there a student discount?", "학생 할인 있어요?"], ["are there many students?", "학생이 많아요?"], ["is it free for children?", "어린이는 무료예요?"]], "ans": 0, "why": ["Descuento: discount.", "descuento는 \"할인\"이에요."]}, {"say": "¿Se pueden hacer fotos?", "opts": [["can you take photos?", "사진 찍어도 돼요?"], ["can you take my photo?", "제 사진 찍어 주실래요?"], ["do you sell photos?", "사진 팔아요?"]], "ans": 0, "why": ["Se puede: it is allowed.", "se puede는 \"해도 된다\"예요."]}, {"say": "¿Hay que hacer cola?", "opts": [["do we have to queue?", "줄 서야 해요?"], ["is there a cola drink?", "콜라 있어요?"], ["is it far?", "멀어요?"]], "ans": 0, "why": ["Hacer cola: to stand in line.", "hacer cola는 \"줄 서다\"예요."]}, {"say": "Es gratis a partir de las seis", "opts": [["it is free from six o'clock", "여섯 시부터 무료예요"], ["it costs six euros", "6유로예요"], ["it closes at six", "여섯 시에 닫아요"]], "ans": 0, "why": ["Gratis: free. A partir de: from.", "gratis는 \"무료\", a partir de는 \"~부터\"예요."]}, {"say": "¿Dónde está el guardarropa?", "opts": [["where is the cloakroom?", "물품 보관소가 어디예요?"], ["where is the gift shop?", "기념품 가게가 어디예요?"], ["where is the guard?", "경비원이 어디 있어요?"]], "ans": 0, "why": ["Guardarropa: literally keeps clothes.", "guardarropa는 직역하면 \"옷을 지키는 곳\"이에요."]}], "speak": [{"w": "Dos entradas, por favor", "m": ["two tickets, please", "입장권 두 장 주세요"], "n": ["dos en-TRA-das.", "\"도스 엔뜨라다스\"."]}, {"w": "¿Hay descuento para estudiantes?", "m": ["is there a student discount?", "학생 할인 있어요?"], "n": ["eye des-KWEN-to PA-ra es-too-DYAN-tes.", "\"아이 데스꾸엔또 빠라 에스뚜디안떼스\"."]}, {"w": "¿Se pueden hacer fotos?", "m": ["can you take photos?", "사진 찍어도 돼요?"], "n": ["seh PWEH-den a-THEHR FO-tos.", "\"세 뿌에덴 아쎄르 포또스\"."]}, {"w": "¿Hay que hacer cola?", "m": ["do we have to queue?", "줄 서야 해요?"], "n": ["eye keh a-THEHR KO-la.", "\"아이 께 아쎄르 꼴라\"."]}], "build": [{"s": "Una entrada para el museo", "m": ["a ticket for the museum", "박물관 입장권 한 장"]}, {"s": "¿Cuándo es gratis el museo?", "m": ["when is the museum free?", "박물관은 언제 무료예요?"]}, {"s": "No se pueden hacer fotos", "m": ["you cannot take photos", "사진은 찍으면 안 돼요"]}, {"s": "Hay mucha cola", "m": ["there is a long queue", "줄이 길어요"]}], "note": ["The Prado, the Reina Sofía, and the Thyssen form Madrid's golden triangle of art. At the Prado you can stand in front of Velázquez's Las Meninas, and at the Reina Sofía, in front of Picasso's Guernica. Next to the Prado lies the Retiro park, perfect for resting your eyes.", "프라도, 레이나 소피아, 티센은 마드리드 예술의 황금 삼각지대예요. 프라도에서는 벨라스케스의 \"시녀들\" 앞에, 레이나 소피아에서는 피카소의 \"게르니카\" 앞에 설 수 있어요. 프라도 옆에는 레티로 공원이 있어서 눈을 쉬기에 딱 좋아요."], "today": [0, 1, 2]};
LESSONS8[4] = {"guide": "lucia", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¿Cuánto tarda el tren a Toledo?", "m": ["how long does the train to Toledo take?", "톨레도까지 기차로 얼마나 걸려요?"]}, {"w": "Tarda media hora", "m": ["it takes half an hour", "30분 걸려요"]}, {"w": "¿A qué hora sale el último tren?", "m": ["what time does the last train leave?", "막차는 몇 시에 출발해요?"]}, {"w": "Vamos a pasar el día en Toledo", "m": ["we are going to spend the day in Toledo", "톨레도에서 하루를 보낼 거예요"]}, {"w": "Volvemos por la tarde", "m": ["we come back in the afternoon", "오후에 돌아와요"]}, {"w": "No quiero perder el tren", "m": ["I do not want to miss the train", "기차를 놓치고 싶지 않아요"]}], "intro": ["Toledo is the perfect day trip from Madrid. Today you will plan the day: how long the train takes, when to come back, and how not to miss the last train.", "톨레도는 마드리드에서 당일치기로 딱 좋은 곳이에요. 오늘은 하루 계획을 세워요. 기차로 얼마나 걸리는지, 언제 돌아오는지, 막차를 놓치지 않으려면 어떻게 하는지."], "tip": ["Tardar, from Hontanas, also works for trains: ¿cuánto tarda el tren? Media hora is half an hour, and una hora y media is an hour and a half. El último tren is the last train. Pasar el día means to spend the day. Perder means to lose, and also to miss a train: no quiero perder el tren. Day trains to Toledo sell out on weekends, so buy the return ticket in the morning.", "온타나스에서 배운 tardar는 기차에도 써요. ¿cuánto tarda el tren? media hora는 30분, una hora y media는 1시간 반이에요. el último tren은 막차예요. pasar el día는 \"하루를 보내다\"예요. perder는 \"잃다\"이면서 기차를 \"놓치다\"이기도 해요. no quiero perder el tren. 주말에는 톨레도행 기차가 매진되니 돌아오는 표는 아침에 사 두세요."], "choose": [{"say": "¿Cuánto tarda el tren a Toledo?", "opts": [["how long does the train to Toledo take?", "톨레도까지 기차로 얼마나 걸려요?"], ["how much is the train to Toledo?", "톨레도행 기차는 얼마예요?"], ["is the train to Toledo late?", "톨레도행 기차가 늦어요?"]], "ans": 0, "why": ["Tardar: to take time. Costar: to cost.", "tardar는 \"시간이 걸리다\", costar는 \"값이 들다\"예요."]}, {"say": "Tarda media hora", "opts": [["it takes half an hour", "30분 걸려요"], ["it leaves at half past", "30분에 출발해요"], ["it takes an hour and a half", "1시간 반 걸려요"]], "ans": 0, "why": ["Media hora: half an hour.", "media hora는 \"30분\"이에요."]}, {"say": "¿A qué hora sale el último tren?", "opts": [["what time does the last train leave?", "막차는 몇 시에 출발해요?"], ["what time does the first train leave?", "첫차는 몇 시에 출발해요?"], ["when did the train arrive?", "기차는 언제 도착했어요?"]], "ans": 0, "why": ["Último: last. Primero: first.", "último는 \"마지막\", primero는 \"첫 번째\"예요."]}, {"say": "Vamos a pasar el día en Toledo", "opts": [["we are going to spend the day in Toledo", "톨레도에서 하루를 보낼 거예요"], ["we are going to pass through Toledo", "톨레도를 지나갈 거예요"], ["we spent a day in Toledo", "톨레도에서 하루를 보냈어요"]], "ans": 0, "why": ["Pasar el día: to spend the day.", "pasar el día는 \"하루를 보내다\"예요."]}, {"say": "No quiero perder el tren", "opts": [["I do not want to miss the train", "기차를 놓치고 싶지 않아요"], ["I do not want to take the train", "기차 타기 싫어요"], ["I lost my train ticket", "기차표를 잃어버렸어요"]], "ans": 0, "why": ["Perder el tren: to miss the train.", "perder el tren은 \"기차를 놓치다\"예요."]}, {"say": "Volvemos por la tarde", "opts": [["we come back in the afternoon", "오후에 돌아와요"], ["we leave in the morning", "아침에 떠나요"], ["we came back late", "늦게 돌아왔어요"]], "ans": 0, "why": ["Volver: to come back.", "volver는 \"돌아오다\"예요."]}], "speak": [{"w": "¿Cuánto tarda el tren a Toledo?", "m": ["how long does the train to Toledo take?", "톨레도까지 기차로 얼마나 걸려요?"], "n": ["KWAN-to TAR-da el tren a to-LEH-do.", "\"꾸안또 따르다 엘 뜨렌 아 똘레도\"."]}, {"w": "Tarda media hora", "m": ["it takes half an hour", "30분 걸려요"], "n": ["TAR-da MEH-dya O-ra.", "\"따르다 메디아 오라\"."]}, {"w": "¿A qué hora sale el último tren?", "m": ["what time does the last train leave?", "막차는 몇 시에 출발해요?"], "n": ["a keh O-ra SA-leh el OOL-tee-mo tren.", "\"아 께 오라 살레 엘 울띠모 뜨렌\"."]}, {"w": "No quiero perder el tren", "m": ["I do not want to miss the train", "기차를 놓치고 싶지 않아요"], "n": ["no KYEH-ro per-DEHR el tren.", "\"노 끼에로 뻬르데르 엘 뜨렌\"."]}], "build": [{"s": "El tren tarda una hora y media", "m": ["the train takes an hour and a half", "기차로 1시간 반 걸려요"]}, {"s": "El último tren sale a las nueve", "m": ["the last train leaves at nine", "막차는 아홉 시에 출발해요"]}, {"s": "Vamos a volver por la noche", "m": ["we are going to come back at night", "밤에 돌아올 거예요"]}, {"s": "¡Corre, que perdemos el tren!", "m": ["run, we are going to miss the train!", "뛰어, 기차 놓치겠어!"], "why": ["Corre: run, between friends.", "corre는 친구 사이의 \"뛰어\"예요."]}], "note": ["Toledo's station is a beauty in itself, built about a hundred years ago in the Neo Mudéjar style, with brick, tiles, and a clock tower. From there, a short bus ride or a steep walk takes you up into the old city.", "톨레도역은 그 자체로 아름다워요. 약 100년 전에 네오 무데하르 양식으로 지었고, 벽돌과 타일, 시계탑이 있어요. 역에서 버스를 잠깐 타거나 가파른 길을 걸어 올라가면 옛 도시에 닿아요."], "today": [0, 1, 2]};
LESSONS8[5] = {"guide": "ramon", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Me he perdido", "m": ["I am lost", "길을 잃었어요"], "n": ["Literally, I have lost myself.", "직역하면 \"나 자신을 잃어버렸어요\"."]}, {"w": "¿Estamos cerca de la catedral?", "m": ["are we close to the cathedral?", "대성당 가까이 왔어요?"]}, {"w": "Esta calle es muy estrecha", "m": ["this street is very narrow", "이 길은 아주 좁아요"]}, {"w": "Hay que subir", "m": ["you have to go up", "올라가야 해요"]}, {"w": "Baje por esta calle", "m": ["go down this street", "이 길로 내려가세요"]}, {"w": "¿Me lo puede enseñar en el mapa?", "m": ["can you show me on the map?", "지도에서 보여 주실래요?"]}], "intro": ["Toledo's old town is a maze of narrow, steep streets on top of a hill, wrapped by a river. Everyone gets lost here, and that is half the fun. Today you will find your way again.", "톨레도 옛 시가지는 강이 감싸 도는 언덕 위, 좁고 가파른 골목이 얽힌 미로예요. 여기서는 누구나 길을 잃고, 그게 재미의 절반이에요. 오늘은 다시 길을 찾는 법을 배워요."], "tip": ["Me he perdido is the classic way to say I am lost. Subir is to go up and bajar is to go down, so in Toledo you will hear both a lot. Baje, go down, and suba, go up, are the polite forms people use to give directions. Estrecha means narrow. If words are not enough, ask ¿me lo puede enseñar en el mapa?, and enseñar here means to show.", "me he perdido는 \"길을 잃었어요\"라는 대표적인 말이에요. subir는 \"올라가다\", bajar는 \"내려가다\"라서 톨레도에서는 둘 다 많이 들어요. baje(내려가세요), suba(올라가세요)는 길을 알려 줄 때 쓰는 공손한 말이에요. estrecha는 \"좁은\"이에요. 말로 부족하면 ¿me lo puede enseñar en el mapa?라고 물어요. 여기서 enseñar는 \"보여 주다\"예요."], "choose": [{"say": "Me he perdido", "opts": [["I am lost", "길을 잃었어요"], ["I lost my phone", "휴대폰을 잃어버렸어요"], ["I am tired", "피곤해요"]], "ans": 0, "why": ["Perderse: to get lost.", "perderse는 \"길을 잃다\"예요."]}, {"say": "¿Estamos cerca de la catedral?", "opts": [["are we close to the cathedral?", "대성당 가까이 왔어요?"], ["is the cathedral closed?", "대성당 문 닫았어요?"], ["are we inside the cathedral?", "대성당 안이에요?"]], "ans": 0, "why": ["Cerca de: close to.", "cerca de는 \"~가까이\"예요."]}, {"say": "Esta calle es muy estrecha", "opts": [["this street is very narrow", "이 길은 아주 좁아요"], ["this street is very long", "이 길은 아주 길어요"], ["this street is very busy", "이 길은 아주 붐벼요"]], "ans": 0, "why": ["Estrecho: narrow. Ancho: wide.", "estrecho는 \"좁은\", ancho는 \"넓은\"이에요."]}, {"say": "Hay que subir", "opts": [["you have to go up", "올라가야 해요"], ["you have to go down", "내려가야 해요"], ["you have to turn", "돌아야 해요"]], "ans": 0, "why": ["Hay que: one has to. Subir: to go up.", "hay que는 \"~해야 한다\", subir는 \"올라가다\"예요."]}, {"say": "Baje por esta calle", "opts": [["go down this street", "이 길로 내려가세요"], ["go up this street", "이 길로 올라가세요"], ["cross this street", "이 길을 건너세요"]], "ans": 0, "why": ["Baje: the polite go down.", "baje는 공손한 \"내려가세요\"예요."]}, {"say": "¿Me lo puede enseñar en el mapa?", "opts": [["can you show me on the map?", "지도에서 보여 주실래요?"], ["can you sell me a map?", "지도 파실래요?"], ["can you teach me Spanish?", "스페인어 가르쳐 주실래요?"]], "ans": 0, "why": ["Enseñar: to show, and also to teach.", "enseñar는 \"보여 주다\"이자 \"가르치다\"예요."]}], "speak": [{"w": "Me he perdido", "m": ["I am lost", "길을 잃었어요"], "n": ["meh eh per-DEE-do.", "\"메 에 뻬르디도\"."]}, {"w": "Esta calle es muy estrecha", "m": ["this street is very narrow", "이 길은 아주 좁아요"], "n": ["ES-ta KA-yeh es mwee es-TREH-cha.", "\"에스따 까예 에스 무이 에스뜨레차\"."]}, {"w": "Hay que subir", "m": ["you have to go up", "올라가야 해요"], "n": ["eye keh soo-BEER.", "\"아이 께 수비르\"."]}, {"w": "¿Me lo puede enseñar en el mapa?", "m": ["can you show me on the map?", "지도에서 보여 주실래요?"], "n": ["meh lo PWEH-deh en-seh-NYAR en el MA-pa.", "\"메 로 뿌에데 엔세냐르 엔 엘 마빠\"."]}], "build": [{"s": "Perdone, me he perdido", "m": ["excuse me, I am lost", "실례합니다, 길을 잃었어요"]}, {"s": "Suba por esta calle", "m": ["go up this street", "이 길로 올라가세요"]}, {"s": "La catedral está muy cerca", "m": ["the cathedral is very close", "대성당은 아주 가까워요"]}, {"s": "¿Me lo enseña en el mapa?", "m": ["will you show me on the map?", "지도에서 보여 주실래요?"]}], "note": ["Toledo is called the city of three cultures, because for centuries Christians, Muslims, and Jews lived side by side here. Within a few streets you can visit a cathedral, a mosque that became a church, and two old synagogues. The whole old town is a UNESCO World Heritage Site.", "톨레도는 \"세 문화의 도시\"라고 불려요. 수백 년 동안 기독교인, 무슬림, 유대인이 이곳에서 함께 살았기 때문이에요. 골목 몇 개만 지나면 대성당, 성당이 된 모스크, 옛 유대교 회당 두 곳을 볼 수 있어요. 옛 시가지 전체가 유네스코 세계유산이에요."], "today": [0, 1, 3]};
LESSONS8[6] = {"guide": "begona", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¿Qué es lo típico de Toledo?", "m": ["what is typical of Toledo?", "톨레도의 특산품은 뭐예요?"]}, {"w": "El mazapán", "m": ["marzipan", "마사판 (아몬드 과자)"]}, {"w": "¿Lo hacen aquí?", "m": ["do you make it here?", "여기서 만들어요?"]}, {"w": "Una caja pequeña de mazapán", "m": ["a small box of marzipan", "작은 마사판 한 상자"]}, {"w": "¿Puedo probar uno?", "m": ["can I try one?", "하나 맛봐도 돼요?"]}, {"w": "Está riquísimo", "m": ["it is delicious", "정말 맛있어요"], "n": ["Rico means tasty for food. Riquísimo: very tasty.", "음식에서 rico는 \"맛있는\", riquísimo는 \"정말 맛있는\"이에요."]}], "intro": ["Toledo is famous for two things you can take home: sweet marzipan and steel swords. Today you will buy a sweet souvenir and taste before you buy.", "톨레도는 집에 가져갈 수 있는 두 가지로 유명해요. 달콤한 마사판과 강철 검이에요. 오늘은 달콤한 기념품을 사고, 사기 전에 맛도 봐요."], "tip": ["Lo típico means the typical thing, the local specialty. Probar means to taste or to try: ¿puedo probar uno? For food, rico means delicious, and adding ísimo makes it stronger: riquísimo, buenísimo. Toledo's marzipan is made of almonds and sugar, and the best is said to come from the convents, where nuns have made it for centuries.", "lo típico는 \"그 지역 특산품\"이에요. probar는 \"맛보다, 해 보다\"예요. ¿puedo probar uno? 음식에서 rico는 \"맛있는\"이고, ísimo를 붙이면 더 강해져요. riquísimo, buenísimo. 톨레도 마사판은 아몬드와 설탕으로 만들고, 수백 년 동안 수녀들이 만들어 온 수녀원의 것이 가장 맛있다고들 해요."], "choose": [{"say": "¿Qué es lo típico de Toledo?", "opts": [["what is typical of Toledo?", "톨레도의 특산품은 뭐예요?"], ["what is the type of Toledo?", "톨레도는 어떤 유형이에요?"], ["where is Toledo?", "톨레도는 어디예요?"]], "ans": 0, "why": ["Lo típico: the typical thing.", "lo típico는 \"전형적인 것, 특산품\"이에요."]}, {"say": "El mazapán", "opts": [["marzipan", "마사판 (아몬드 과자)"], ["the map", "지도"], ["the bread", "빵"]], "ans": 0, "why": ["Mazapán: a sweet of almonds and sugar.", "mazapán은 아몬드와 설탕으로 만든 과자예요."]}, {"say": "¿Lo hacen aquí?", "opts": [["do you make it here?", "여기서 만들어요?"], ["do you sell it here?", "여기서 팔아요?"], ["can I eat it here?", "여기서 먹어도 돼요?"]], "ans": 0, "why": ["Hacer: to make.", "hacer는 \"만들다\"예요."]}, {"say": "Una caja pequeña de mazapán", "opts": [["a small box of marzipan", "작은 마사판 한 상자"], ["a big box of marzipan", "큰 마사판 한 상자"], ["a piece of marzipan", "마사판 한 조각"]], "ans": 0, "why": ["Caja: box.", "caja는 \"상자\"예요."]}, {"say": "¿Puedo probar uno?", "opts": [["can I try one?", "하나 맛봐도 돼요?"], ["can I buy one?", "하나 사도 돼요?"], ["can I try it on?", "입어 봐도 돼요?"]], "ans": 0, "why": ["Probar: to taste. Probarse: to try on clothes.", "probar는 \"맛보다\", probarse는 옷을 \"입어 보다\"예요."]}, {"say": "Está riquísimo", "opts": [["it is delicious", "정말 맛있어요"], ["it is very rich", "아주 부자예요"], ["it is very expensive", "아주 비싸요"]], "ans": 0, "why": ["Riquísimo: very tasty.", "riquísimo는 \"정말 맛있는\"이에요."]}], "speak": [{"w": "¿Qué es lo típico de Toledo?", "m": ["what is typical of Toledo?", "톨레도의 특산품은 뭐예요?"], "n": ["keh es lo TEE-pee-ko deh to-LEH-do.", "\"께 에스 로 띠삐꼬 데 똘레도\"."]}, {"w": "El mazapán", "m": ["marzipan", "마사판 (아몬드 과자)"], "n": ["el ma-tha-PAN.", "\"엘 마싸빤\"."]}, {"w": "¿Puedo probar uno?", "m": ["can I try one?", "하나 맛봐도 돼요?"], "n": ["PWEH-do pro-BAR OO-no.", "\"뿌에도 쁘로바르 우노\"."]}, {"w": "Está riquísimo", "m": ["it is delicious", "정말 맛있어요"], "n": ["es-TA rree-KEE-see-mo.", "\"에스따 리끼시모\"."]}], "build": [{"s": "Quería una caja de mazapán", "m": ["I would like a box of marzipan", "마사판 한 상자 주세요"]}, {"s": "¿Puedo probar un poco?", "m": ["can I try a little?", "조금 맛봐도 돼요?"]}, {"s": "Es para regalar", "m": ["it is to give as a gift", "선물할 거예요"]}, {"s": "¡Qué rico está!", "m": ["how tasty it is!", "정말 맛있다!"]}], "note": ["For centuries, Toledo's blacksmiths made some of the best sword blades in Europe, and the city still sells decorative swords today. Its convents, meanwhile, kept the sweet tradition of marzipan, often sold through a small turning window so that the nuns stay out of sight.", "톨레도의 대장장이들은 수백 년 동안 유럽 최고의 칼날을 만들었고, 지금도 장식용 검을 팔아요. 한편 수녀원들은 마사판이라는 달콤한 전통을 지켜 왔어요. 수녀들이 모습을 드러내지 않도록 작은 회전 창구로 파는 경우가 많아요."], "today": [0, 1, 2]};
LESSONS8[7] = {"guide": "lucia", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¿Cuál es mi asiento?", "m": ["which is my seat?", "제 자리는 어디예요?"]}, {"w": "Coche cuatro, asiento doce", "m": ["car four, seat twelve", "4호차 12번 좌석"]}, {"w": "Perdone, creo que es mi asiento", "m": ["excuse me, I think that is my seat", "실례합니다, 제 자리 같아요"]}, {"w": "¿Ventanilla o pasillo?", "m": ["window or aisle?", "창가요, 통로요?"]}, {"w": "¿Hay cafetería en el tren?", "m": ["is there a café on the train?", "기차에 카페 칸 있어요?"]}, {"w": "¿Puedo poner aquí la maleta?", "m": ["can I put my suitcase here?", "여기에 짐 놓아도 돼요?"]}], "intro": ["From Madrid, the high speed train flies south to Seville in about two and a half hours. Today you will find your seat, deal with someone in it, and settle in.", "마드리드에서 고속 열차를 타면 두 시간 반 남짓이면 남쪽의 세비야에 닿아요. 오늘은 자리를 찾고, 내 자리에 앉은 사람에게 말하고, 편히 자리 잡는 법을 배워요."], "tip": ["On Spanish trains a carriage is a coche, not a vagón on your ticket, and your seat is an asiento. Ventanilla is a window seat and pasillo an aisle seat. If someone is in your seat, say perdone, creo que es mi asiento, I think it is my seat, which is polite and usually works. Maleta is a suitcase, and there are racks at the end of each car.", "스페인 기차표에서는 칸을 vagón이 아니라 coche라고 하고, 좌석은 asiento예요. ventanilla는 창가, pasillo는 통로 자리예요. 누가 내 자리에 앉아 있으면 perdone, creo que es mi asiento(실례합니다, 제 자리 같아요)라고 해요. 공손하고 보통 통해요. maleta는 여행 가방이고, 칸마다 끝에 짐 선반이 있어요."], "choose": [{"say": "¿Cuál es mi asiento?", "opts": [["which is my seat?", "제 자리는 어디예요?"], ["which is my car?", "제 차는 어느 거예요?"], ["when is my train?", "제 기차는 언제예요?"]], "ans": 0, "why": ["Asiento: seat.", "asiento는 \"좌석\"이에요."]}, {"say": "Coche cuatro, asiento doce", "opts": [["car four, seat twelve", "4호차 12번 좌석"], ["car twelve, seat four", "12호차 4번 좌석"], ["four cars, twelve seats", "4칸, 12자리"]], "ans": 0, "why": ["On trains, coche is the carriage.", "기차에서 coche는 \"칸\"이에요."]}, {"say": "Perdone, creo que es mi asiento", "opts": [["excuse me, I think that is my seat", "실례합니다, 제 자리 같아요"], ["excuse me, is this seat free?", "실례합니다, 이 자리 비었어요?"], ["sorry, I am in your seat", "죄송해요, 제가 당신 자리에 앉았네요"]], "ans": 0, "why": ["Creo que: I think that.", "creo que는 \"~인 것 같아요\"예요."]}, {"say": "¿Ventanilla o pasillo?", "opts": [["window or aisle?", "창가요, 통로요?"], ["window or door?", "창문이요, 문이요?"], ["front or back?", "앞이요, 뒤요?"]], "ans": 0, "why": ["Ventanilla: small window. Pasillo: corridor, aisle.", "ventanilla는 \"작은 창\", pasillo는 \"통로\"예요."]}, {"say": "¿Hay cafetería en el tren?", "opts": [["is there a café on the train?", "기차에 카페 칸 있어요?"], ["is there coffee at the station?", "역에 커피 있어요?"], ["is the café open?", "카페 열었어요?"]], "ans": 0, "why": ["Cafetería: café.", "cafetería는 \"카페\"예요."]}, {"say": "¿Puedo poner aquí la maleta?", "opts": [["can I put my suitcase here?", "여기에 짐 놓아도 돼요?"], ["can I open my suitcase?", "가방 열어도 돼요?"], ["where is my suitcase?", "제 가방이 어디 있어요?"]], "ans": 0, "why": ["Poner: to put. Maleta: suitcase.", "poner는 \"놓다\", maleta는 \"여행 가방\"이에요."]}], "speak": [{"w": "¿Cuál es mi asiento?", "m": ["which is my seat?", "제 자리는 어디예요?"], "n": ["kwal es mee a-SYEN-to.", "\"꾸알 에스 미 아시엔또\"."]}, {"w": "Perdone, creo que es mi asiento", "m": ["excuse me, I think that is my seat", "실례합니다, 제 자리 같아요"], "n": ["per-DO-neh, KREH-o keh es mee a-SYEN-to.", "\"뻬르도네, 끄레오 께 에스 미 아시엔또\"."]}, {"w": "¿Ventanilla o pasillo?", "m": ["window or aisle?", "창가요, 통로요?"], "n": ["ben-ta-NEE-ya o pa-SEE-yo.", "\"벤따니야 오 빠시요\"."]}, {"w": "¿Puedo poner aquí la maleta?", "m": ["can I put my suitcase here?", "여기에 짐 놓아도 돼요?"], "n": ["PWEH-do po-NEHR a-KEE la ma-LEH-ta.", "\"뿌에도 뽀네르 아끼 라 말레따\"."]}], "build": [{"s": "Mi asiento es el doce", "m": ["my seat is number twelve", "제 자리는 12번이에요"]}, {"s": "Prefiero ventanilla", "m": ["I prefer a window seat", "창가가 좋아요"]}, {"s": "¿Está libre este asiento?", "m": ["is this seat free?", "이 자리 비었어요?"]}, {"s": "La cafetería está en el coche cinco", "m": ["the café is in car five", "카페 칸은 5호차예요"]}], "note": ["Spain's first high speed line opened in 1992, linking Madrid and Seville in time for the Seville World's Fair. Today Spain has one of the longest high speed rail networks in the world.", "스페인 최초의 고속 철도는 세비야 세계 박람회에 맞춰 1992년에 개통해 마드리드와 세비야를 이었어요. 지금 스페인은 세계에서 가장 긴 고속 철도망을 가진 나라 가운데 하나예요."], "today": [0, 1, 2]};
LESSONS8[8] = {"guide": "ramon", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¿Salimos esta noche?", "m": ["shall we go out tonight?", "오늘 밤에 나갈까?"]}, {"w": "¿Dónde hay un espectáculo de flamenco?", "m": ["where is there a flamenco show?", "플라멩코 공연은 어디서 해요?"]}, {"w": "¿A qué hora empieza?", "m": ["what time does it start?", "몇 시에 시작해요?"]}, {"w": "¿Cuánto dura?", "m": ["how long does it last?", "얼마나 해요?"]}, {"w": "Quedamos a las nueve en la plaza", "m": ["let us meet at nine in the square", "아홉 시에 광장에서 만나자"], "n": ["Quedar: to arrange to meet.", "quedar는 \"만나기로 하다\"예요."]}, {"w": "¡Me ha encantado!", "m": ["I loved it!", "정말 좋았어요!"]}], "intro": ["Seville comes alive at night. Today you will make plans to go out, arrange where to meet, and see a flamenco show.", "세비야는 밤에 살아나요. 오늘은 나갈 계획을 세우고, 어디서 만날지 정하고, 플라멩코 공연을 보러 가요."], "tip": ["Salir means to go out, and ¿salimos? is the friendly we question from Burgos. Empezar is to start and durar to last: ¿a qué hora empieza?, ¿cuánto dura? Quedar is how Spaniards arrange to meet: quedamos a las nueve, we meet at nine. A small, intimate flamenco venue is called a tablao. After the show, ¡me ha encantado!", "salir는 \"나가다\"이고, ¿salimos?는 부르고스에서 배운 친근한 제안이에요. empezar는 \"시작하다\", durar는 \"계속되다\"예요. ¿a qué hora empieza?, ¿cuánto dura? 스페인 사람들은 quedar로 약속을 잡아요. quedamos a las nueve(아홉 시에 만나자). 작고 친밀한 플라멩코 공연장은 tablao라고 해요. 공연이 끝나면 ¡me ha encantado!"], "choose": [{"say": "¿Salimos esta noche?", "opts": [["shall we go out tonight?", "오늘 밤에 나갈까?"], ["shall we leave tomorrow?", "내일 떠날까?"], ["did we go out last night?", "어젯밤에 나갔었어?"]], "ans": 0, "why": ["Salir: to go out.", "salir는 \"나가다\"예요."]}, {"say": "¿A qué hora empieza?", "opts": [["what time does it start?", "몇 시에 시작해요?"], ["what time does it end?", "몇 시에 끝나요?"], ["how long is it?", "얼마나 해요?"]], "ans": 0, "why": ["Empezar: to start. Terminar: to end.", "empezar는 \"시작하다\", terminar는 \"끝나다\"예요."]}, {"say": "¿Cuánto dura?", "opts": [["how long does it last?", "얼마나 해요?"], ["how hard is it?", "얼마나 어려워요?"], ["how much is it?", "얼마예요?"]], "ans": 0, "why": ["Durar: to last. Duro: hard.", "durar는 \"계속되다\", duro는 \"딱딱한\"이에요."]}, {"say": "Quedamos a las nueve en la plaza", "opts": [["let us meet at nine in the square", "아홉 시에 광장에서 만나자"], ["we stay in the square until nine", "아홉 시까지 광장에 있어요"], ["the square closes at nine", "광장은 아홉 시에 닫아요"]], "ans": 0, "why": ["Quedar: to meet up.", "quedar는 \"만나기로 하다\"예요."]}, {"say": "¿Dónde hay un espectáculo de flamenco?", "opts": [["where is there a flamenco show?", "플라멩코 공연은 어디서 해요?"], ["where can I learn flamenco?", "플라멩코는 어디서 배워요?"], ["is flamenco from here?", "플라멩코가 여기서 왔어요?"]], "ans": 0, "why": ["Espectáculo: show.", "espectáculo는 \"공연\"이에요."]}, {"say": "¡Me ha encantado!", "opts": [["I loved it!", "정말 좋았어요!"], ["I am enchanted to meet you!", "만나서 반가워요!"], ["I want more!", "더 보고 싶어요!"]], "ans": 0, "why": ["From Samos.", "사모스에서 배웠어요."]}], "speak": [{"w": "¿Salimos esta noche?", "m": ["shall we go out tonight?", "오늘 밤에 나갈까?"], "n": ["sa-LEE-mos ES-ta NO-cheh.", "\"살리모스 에스따 노체\"."]}, {"w": "¿A qué hora empieza?", "m": ["what time does it start?", "몇 시에 시작해요?"], "n": ["a keh O-ra em-PYEH-tha.", "\"아 께 오라 엠삐에싸\"."]}, {"w": "Quedamos a las nueve en la plaza", "m": ["let us meet at nine in the square", "아홉 시에 광장에서 만나자"], "n": ["keh-DA-mos a las NWEH-beh en la PLA-tha.", "\"께다모스 아 라스 누에베 엔 라 쁠라싸\"."]}, {"w": "¡Me ha encantado!", "m": ["I loved it!", "정말 좋았어요!"], "n": ["meh a en-kan-TA-do.", "\"메 아 엔깐따도\"."]}], "build": [{"s": "El espectáculo empieza a las diez", "m": ["the show starts at ten", "공연은 열 시에 시작해요"]}, {"s": "Dura una hora más o menos", "m": ["it lasts about an hour", "한 시간쯤 해요"], "why": ["Más o menos: more or less.", "más o menos는 \"대략\"이에요."]}, {"s": "¿Dónde quedamos?", "m": ["where shall we meet?", "어디서 만날까?"]}, {"s": "Quedamos delante de la catedral", "m": ["let us meet in front of the cathedral", "대성당 앞에서 만나자"]}], "note": ["Flamenco grew up in Andalusia, from the songs and dances of Roma communities mixed with many other traditions, and it is on UNESCO's list of the cultural heritage of humanity. In Seville, the neighborhood of Triana, across the river, is one of its historic homes.", "플라멩코는 안달루시아에서 로마(집시) 공동체의 노래와 춤이 여러 전통과 섞이며 자라났고, 유네스코 인류무형문화유산에 올라 있어요. 세비야에서는 강 건너 트리아나 지구가 플라멩코의 오랜 고향 가운데 하나예요."], "today": [0, 1, 2]};
LESSONS8[9] = {"guide": "begona", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¡Qué calor hace!", "m": ["it is so hot!", "정말 덥다!"]}, {"w": "Vamos a la sombra", "m": ["let us go to the shade", "그늘로 가자"]}, {"w": "Necesito beber agua", "m": ["I need to drink water", "물을 마셔야 해요"]}, {"w": "A mediodía no salgas", "m": ["do not go out at midday", "한낮에는 나가지 마"]}, {"w": "Mejor por la tarde, cuando refresca", "m": ["better in the evening, when it cools down", "저녁에 선선해지면 가는 게 나아요"]}, {"w": "¿Tiene aire acondicionado?", "m": ["does it have air conditioning?", "에어컨 있어요?"]}], "intro": ["In summer, Seville is one of the hottest cities in Europe, and temperatures above forty degrees are common. Today you will learn to talk about the heat and live like a sevillano.", "여름의 세비야는 유럽에서 가장 더운 도시 가운데 하나로, 40도가 넘는 날도 흔해요. 오늘은 더위에 대해 말하고 세비야 사람처럼 지내는 법을 배워요."], "tip": ["From Frómista: hace calor. To make it an exclamation, say ¡qué calor hace! Sombra is shade, and sol is sun. Locals avoid the street at midday and come out when it refresca, cools down, in the evening. No salgas is a friendly do not go out. Necesito plus a verb, from Carrión, says what you need to do.", "프로미스타에서 배운 hace calor를 감탄문으로 만들면 ¡qué calor hace!예요. sombra는 \"그늘\", sol은 \"해\"예요. 이곳 사람들은 한낮에는 거리에 나가지 않고, 저녁에 선선해지면(refresca) 나와요. no salgas는 친근한 \"나가지 마\"예요. 카리온에서 배운 necesito 뒤에 동사를 붙이면 해야 할 일을 말해요."], "choose": [{"say": "¡Qué calor hace!", "opts": [["it is so hot!", "정말 덥다!"], ["what a nice day!", "정말 좋은 날이다!"], ["how cold it is!", "정말 춥다!"]], "ans": 0, "why": ["Calor: heat. Frío: cold.", "calor는 \"더위\", frío는 \"추위\"예요."]}, {"say": "Vamos a la sombra", "opts": [["let us go to the shade", "그늘로 가자"], ["let us go to the beach", "해변으로 가자"], ["let us go home", "집에 가자"]], "ans": 0, "why": ["Sombra: shade, shadow.", "sombra는 \"그늘, 그림자\"예요."]}, {"say": "Necesito beber agua", "opts": [["I need to drink water", "물을 마셔야 해요"], ["I need to buy water", "물을 사야 해요"], ["I drank water", "물을 마셨어요"]], "ans": 0, "why": ["Beber: to drink.", "beber는 \"마시다\"예요."]}, {"say": "A mediodía no salgas", "opts": [["do not go out at midday", "한낮에는 나가지 마"], ["go out at midday", "한낮에 나가"], ["we left at noon", "정오에 떠났어"]], "ans": 0, "why": ["No salgas: do not go out.", "no salgas는 \"나가지 마\"예요."]}, {"say": "Mejor por la tarde, cuando refresca", "opts": [["better in the evening, when it cools down", "저녁에 선선해지면 가는 게 나아요"], ["the afternoon is hotter", "오후가 더 더워요"], ["better in the morning, when it is fresh", "아침에 상쾌할 때가 나아요"]], "ans": 0, "why": ["Refrescar: to cool down.", "refrescar는 \"선선해지다\"예요."]}, {"say": "¿Tiene aire acondicionado?", "opts": [["does it have air conditioning?", "에어컨 있어요?"], ["is there fresh air?", "바람 좀 통해요?"], ["does it have heating?", "난방 있어요?"]], "ans": 0, "why": ["Aire acondicionado: air conditioning.", "aire acondicionado는 \"에어컨\"이에요."]}], "speak": [{"w": "¡Qué calor hace!", "m": ["it is so hot!", "정말 덥다!"], "n": ["keh ka-LOR A-theh.", "\"께 깔로르 아쎄\"."]}, {"w": "Vamos a la sombra", "m": ["let us go to the shade", "그늘로 가자"], "n": ["BA-mos a la SOM-bra.", "\"바모스 아 라 솜브라\"."]}, {"w": "Necesito beber agua", "m": ["I need to drink water", "물을 마셔야 해요"], "n": ["neh-theh-SEE-to beh-BEHR A-gwa.", "\"네쎄시또 베베르 아구아\"."]}, {"w": "¿Tiene aire acondicionado?", "m": ["does it have air conditioning?", "에어컨 있어요?"], "n": ["TYEH-neh AY-reh a-kon-dee-thyo-NA-do.", "\"띠에네 아이레 아꼰디씨오나도\"."]}], "build": [{"s": "Hoy hace mucho calor", "m": ["today it is very hot", "오늘 정말 더워요"]}, {"s": "Prefiero salir por la tarde", "m": ["I prefer to go out in the evening", "저녁에 나가는 게 좋아요"]}, {"s": "Vamos a sentarnos a la sombra", "m": ["let us sit in the shade", "그늘에 앉자"]}, {"s": "Necesito un abanico", "m": ["I need a fan", "부채가 필요해요"], "why": ["Abanico: a hand fan, very Sevillian.", "abanico는 아주 세비야다운 손부채예요."]}], "note": ["Seville's Giralda tower was once the minaret of a great mosque and became the bell tower of the cathedral. Instead of stairs, it has a long series of ramps inside, built so that a guard could ride up on horseback. From the top you see the whole white city.", "세비야의 히랄다 탑은 원래 큰 모스크의 첨탑이었고, 대성당의 종탑이 되었어요. 안에는 계단 대신 길게 이어진 경사로가 있는데, 사람이 말을 타고 올라갈 수 있게 만든 거예요. 꼭대기에서는 하얀 도시 전체가 내려다보여요."], "today": [0, 1, 2]};
LESSONS8[10] = {"guide": "lucia", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Quería dos entradas para la Alhambra", "m": ["I would like two tickets for the Alhambra", "알람브라 입장권 두 장 주세요"]}, {"w": "Lo siento, están agotadas", "m": ["sorry, they are sold out", "죄송해요, 매진됐어요"], "n": ["Agotado: sold out, used up.", "agotado는 \"매진된, 다 떨어진\"이에요."]}, {"w": "¿Hay entradas para mañana?", "m": ["are there tickets for tomorrow?", "내일 표 있어요?"]}, {"w": "¿A qué hora es la entrada a los palacios?", "m": ["what time is the entry to the palaces?", "궁전 입장은 몇 시예요?"]}, {"w": "Hay que llegar puntual", "m": ["you have to arrive on time", "시간 맞춰 와야 해요"]}, {"w": "¿Necesito el pasaporte?", "m": ["do I need my passport?", "여권이 필요해요?"]}], "intro": ["The Alhambra is the most visited monument in Spain, and tickets often sell out weeks ahead. Today you will try to buy tickets and understand the entry rules.", "알람브라는 스페인에서 가장 많은 사람이 찾는 유적이라 몇 주 전에 표가 매진되는 일이 많아요. 오늘은 표를 사 보고 입장 규칙을 알아들어 봐요."], "tip": ["Remember from Madrid: a monument ticket is una entrada. Agotadas means sold out. The Nasrid Palaces, the jewel of the Alhambra, have a fixed entry time printed on your ticket, and if you miss it, you cannot go in, so hay que llegar puntual. Tickets carry your name, so bring the passport or ID you used to book.", "마드리드에서 배운 것처럼 유적 입장권은 entrada예요. agotadas는 \"매진된\"이에요. 알람브라의 보석인 나스르 궁전은 표에 입장 시간이 정해져 있고, 놓치면 들어갈 수 없어요. 그래서 hay que llegar puntual(시간 맞춰 와야 해요). 표에 이름이 적혀 있으니 예매할 때 쓴 여권이나 신분증을 꼭 챙겨요."], "choose": [{"say": "Quería dos entradas para la Alhambra", "opts": [["I would like two tickets for the Alhambra", "알람브라 입장권 두 장 주세요"], ["I would like to enter the Alhambra twice", "알람브라에 두 번 들어가고 싶어요"], ["two entrances to the Alhambra", "알람브라 입구 두 곳"]], "ans": 0, "why": ["Entradas: tickets.", "entradas는 \"입장권\"이에요."]}, {"say": "Lo siento, están agotadas", "opts": [["sorry, they are sold out", "죄송해요, 매진됐어요"], ["sorry, they are tired", "죄송해요, 그들은 지쳤어요"], ["sorry, they are closed", "죄송해요, 문 닫았어요"]], "ans": 0, "why": ["Agotado: sold out. It can also mean exhausted.", "agotado는 \"매진된\"이에요. \"기진맥진한\"이라는 뜻도 있어요."]}, {"say": "¿Hay entradas para mañana?", "opts": [["are there tickets for tomorrow?", "내일 표 있어요?"], ["is it open tomorrow?", "내일 열어요?"], ["is the entrance tomorrow?", "입장이 내일이에요?"]], "ans": 0, "why": ["Para mañana: for tomorrow.", "para mañana는 \"내일 것\"이에요."]}, {"say": "¿A qué hora es la entrada a los palacios?", "opts": [["what time is the entry to the palaces?", "궁전 입장은 몇 시예요?"], ["where is the entrance to the palaces?", "궁전 입구가 어디예요?"], ["how much is the palace ticket?", "궁전 표는 얼마예요?"]], "ans": 0, "why": ["La entrada here is the entry time.", "여기서 la entrada는 \"입장\"이에요."]}, {"say": "Hay que llegar puntual", "opts": [["you have to arrive on time", "시간 맞춰 와야 해요"], ["you have to arrive early", "일찍 와야 해요"], ["you can arrive any time", "아무 때나 와도 돼요"]], "ans": 0, "why": ["Puntual: on time.", "puntual은 \"시간을 지키는\"이에요."]}, {"say": "¿Necesito el pasaporte?", "opts": [["do I need my passport?", "여권이 필요해요?"], ["can I see your passport?", "여권 좀 볼 수 있을까요?"], ["I lost my passport", "여권을 잃어버렸어요"]], "ans": 0, "why": ["Necesito: I need.", "necesito는 \"필요해요\"예요."]}], "speak": [{"w": "Quería dos entradas para la Alhambra", "m": ["I would like two tickets for the Alhambra", "알람브라 입장권 두 장 주세요"], "n": ["keh-REE-a dos en-TRA-das PA-ra la a-LAM-bra.", "\"께리아 도스 엔뜨라다스 빠라 라 알람브라\"."]}, {"w": "Lo siento, están agotadas", "m": ["sorry, they are sold out", "죄송해요, 매진됐어요"], "n": ["lo SYEN-to, es-TAN a-go-TA-das.", "\"로 시엔또, 에스딴 아고따다스\"."]}, {"w": "¿Hay entradas para mañana?", "m": ["are there tickets for tomorrow?", "내일 표 있어요?"], "n": ["eye en-TRA-das PA-ra ma-NYA-na.", "\"아이 엔뜨라다스 빠라 마냐나\"."]}, {"w": "Hay que llegar puntual", "m": ["you have to arrive on time", "시간 맞춰 와야 해요"], "n": ["eye keh yeh-GAR poon-TWAL.", "\"아이 께 예가르 뿐뚜알\"."]}], "build": [{"s": "Las entradas están agotadas", "m": ["the tickets are sold out", "표가 매진됐어요"]}, {"s": "¿Hay entradas para el jueves?", "m": ["are there tickets for Thursday?", "목요일 표 있어요?"]}, {"s": "Mi entrada es a las diez y media", "m": ["my entry is at half past ten", "제 입장은 열 시 반이에요"]}, {"s": "Aquí tiene mi pasaporte", "m": ["here is my passport", "여기 제 여권이에요"]}], "note": ["The Alhambra was the palace city of the Nasrid sultans, the last Muslim rulers in Spain, until 1492. Its walls are covered with carved plaster, tiles, and Arabic poems, and its gardens of the Generalife are full of running water.", "알람브라는 1492년까지 스페인의 마지막 무슬림 통치자였던 나스르 왕조 술탄들의 궁전 도시였어요. 벽은 조각한 석고와 타일, 아랍어 시로 덮여 있고, 헤네랄리페 정원에는 물이 끊임없이 흘러요."], "today": [0, 1, 3]};
LESSONS8[11] = {"guide": "ramon", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Una caña y un tinto de verano", "m": ["a small beer and a red wine summer spritz", "생맥주 한 잔이랑 틴토 데 베라노 한 잔"], "n": ["Tinto de verano: red wine with lemon soda, very popular.", "tinto de verano는 레드 와인에 레몬 탄산수를 섞은, 아주 인기 있는 음료예요."]}, {"w": "¿La tapa es gratis?", "m": ["is the tapa free?", "타파는 공짜예요?"]}, {"w": "Con cada bebida, una tapa", "m": ["with each drink, a tapa", "음료마다 타파 하나"]}, {"w": "¿Qué tapa nos toca?", "m": ["which tapa do we get?", "우리 타파는 뭐가 나와요?"]}, {"w": "Otra ronda, por favor", "m": ["another round, please", "한 잔씩 더 주세요"]}, {"w": "¿Vamos a otro bar?", "m": ["shall we go to another bar?", "다른 바로 갈까?"]}], "intro": ["Granada keeps an old and generous custom: in many bars, every drink comes with a free tapa. Today you will go from bar to bar the Granada way.", "그라나다에는 오래되고 넉넉한 풍습이 있어요. 많은 바에서 음료마다 타파를 공짜로 줘요. 오늘은 그라나다식으로 바에서 바로 옮겨 다녀 봐요."], "tip": ["In Granada you usually do not choose the free tapa: the bar decides, and each new round may bring a different one, so ask ¿qué tapa nos toca? Tocar here means to be your turn, to get. Una ronda is a round of drinks for the group. Going from bar to bar is called ir de tapas or ir de cañas. Remember caña and pincho from Santo Domingo.", "그라나다에서는 보통 공짜 타파를 고르지 않아요. 바에서 정해 주고, 한 잔씩 더 시킬 때마다 다른 게 나올 수 있어요. 그래서 ¿qué tapa nos toca?라고 물어요. 여기서 tocar는 \"차례가 되다, 받게 되다\"예요. una ronda는 일행 모두의 한 잔씩이에요. 바를 옮겨 다니는 건 ir de tapas나 ir de cañas라고 해요. 산토 도밍고에서 배운 caña와 pincho도 떠올려 봐요."], "choose": [{"say": "¿La tapa es gratis?", "opts": [["is the tapa free?", "타파는 공짜예요?"], ["is the tapa big?", "타파가 커요?"], ["is there a tapa menu?", "타파 메뉴 있어요?"]], "ans": 0, "why": ["Gratis: free of charge.", "gratis는 \"무료\"예요."]}, {"say": "Con cada bebida, una tapa", "opts": [["with each drink, a tapa", "음료마다 타파 하나"], ["one tapa for everyone", "모두에게 타파 하나"], ["a tapa costs one drink", "타파는 음료 한 잔 값이에요"]], "ans": 0, "why": ["Cada: each.", "cada는 \"각각, ~마다\"예요."]}, {"say": "¿Qué tapa nos toca?", "opts": [["which tapa do we get?", "우리 타파는 뭐가 나와요?"], ["which tapa do you recommend?", "어떤 타파를 추천하세요?"], ["can I touch the tapa?", "타파 만져도 돼요?"]], "ans": 0, "why": ["Tocar: to touch, and also to be your turn.", "tocar는 \"만지다\"이자 \"차례가 되다\"예요."]}, {"say": "Otra ronda, por favor", "opts": [["another round, please", "한 잔씩 더 주세요"], ["another plate, please", "한 접시 더 주세요"], ["the bill, please", "계산서 주세요"]], "ans": 0, "why": ["Ronda: a round of drinks.", "ronda는 \"한 차례씩 돌리는 술\"이에요."]}, {"say": "¿Vamos a otro bar?", "opts": [["shall we go to another bar?", "다른 바로 갈까?"], ["shall we stay here?", "여기 있을까?"], ["is there another bar?", "다른 바 있어요?"]], "ans": 0, "why": ["Vamos a: let us go to.", "vamos a는 \"~로 가자\"예요."]}, {"say": "Una caña y un tinto de verano", "opts": [["a small beer and a red wine summer spritz", "생맥주 한 잔이랑 틴토 데 베라노 한 잔"], ["a beer and a red wine", "맥주랑 레드 와인"], ["a cane and a summer hat", "지팡이랑 여름 모자"]], "ans": 0, "why": ["Tinto: red wine. Verano: summer.", "tinto는 \"레드 와인\", verano는 \"여름\"이에요."]}], "speak": [{"w": "¿La tapa es gratis?", "m": ["is the tapa free?", "타파는 공짜예요?"], "n": ["la TA-pa es GRA-tees.", "\"라 따빠 에스 그라띠스\"."]}, {"w": "¿Qué tapa nos toca?", "m": ["which tapa do we get?", "우리 타파는 뭐가 나와요?"], "n": ["keh TA-pa nos TO-ka.", "\"께 따빠 노스 또까\"."]}, {"w": "Otra ronda, por favor", "m": ["another round, please", "한 잔씩 더 주세요"], "n": ["O-tra RRON-da.", "\"오뜨라 론다\"."]}, {"w": "¿Vamos a otro bar?", "m": ["shall we go to another bar?", "다른 바로 갈까?"], "n": ["BA-mos a O-tro bar.", "\"바모스 아 오뜨로 바르\"."]}], "build": [{"s": "Dos cañas, por favor", "m": ["two small beers, please", "생맥주 두 잔 주세요"]}, {"s": "Esta tapa está buenísima", "m": ["this tapa is delicious", "이 타파 정말 맛있어요"]}, {"s": "Ponme otra caña", "m": ["another small beer for me", "생맥주 한 잔 더 줘요"], "why": ["Ponme: the friendly form of póngame.", "ponme는 póngame의 친근한 말이에요."]}, {"s": "Vamos de tapas por el centro", "m": ["let us go for tapas in the center", "시내에서 타파 먹으러 가자"]}], "note": ["Granada sits at the foot of the Sierra Nevada, where you can ski in winter and still reach the Mediterranean coast in about an hour. It is also a lively university town, which helps keep its free tapa tradition alive.", "그라나다는 시에라 네바다 산맥 기슭에 있어서, 겨울엔 스키를 타고 한 시간쯤이면 지중해 해안에도 닿을 수 있어요. 활기찬 대학 도시이기도 해서 공짜 타파 전통이 이어지는 데 한몫해요."], "today": [0, 1, 2]};
LESSONS8[12] = {"guide": "begona", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "¿Nos hace una foto, por favor?", "m": ["could you take a photo of us, please?", "저희 사진 좀 찍어 주실래요?"]}, {"w": "Con la Alhambra detrás", "m": ["with the Alhambra behind", "알람브라가 뒤에 나오게"]}, {"w": "Otra, por si acaso", "m": ["another one, just in case", "혹시 모르니 한 장 더요"]}, {"w": "¡Qué vista tan bonita!", "m": ["what a beautiful view!", "정말 멋진 경치다!"]}, {"w": "El sol se está poniendo", "m": ["the sun is setting", "해가 지고 있어요"]}, {"w": "No quiero que se acabe este día", "m": ["I do not want this day to end", "이 하루가 끝나지 않았으면 좋겠어요"]}], "intro": ["At the Mirador de San Nicolás, crowds gather at sunset to watch the Alhambra turn red against the mountains. Today you will ask a stranger for a photo and talk about the view.", "산 니콜라스 전망대에는 해 질 녘이면 산을 배경으로 알람브라가 붉게 물드는 걸 보려고 사람들이 모여요. 오늘은 모르는 사람에게 사진을 부탁하고 경치에 대해 이야기해 봐요."], "tip": ["To ask a favor politely, use usted: ¿nos hace una foto?, will you take a photo of us? Detrás means behind, and delante means in front. Por si acaso is just in case. ¡Qué...tan...! adds strength: ¡qué vista tan bonita!, what a beautiful view! Ponerse, for the sun, means to set: el sol se está poniendo.", "공손하게 부탁할 때는 usted를 써요. ¿nos hace una foto?(저희 사진 찍어 주실래요?) detrás는 \"뒤에\", delante는 \"앞에\"예요. por si acaso는 \"혹시 모르니\"예요. ¡qué...tan...!은 감탄을 더 강하게 해요. ¡qué vista tan bonita!(정말 멋진 경치다!) 해에 쓰는 ponerse는 \"지다\"예요. el sol se está poniendo."], "choose": [{"say": "¿Nos hace una foto, por favor?", "opts": [["could you take a photo of us, please?", "저희 사진 좀 찍어 주실래요?"], ["can I take your photo?", "사진 찍어 드릴까요?"], ["do you have our photo?", "저희 사진 있어요?"]], "ans": 0, "why": ["Nos: us. Hacer una foto: to take a photo.", "nos는 \"우리를\", hacer una foto는 \"사진을 찍다\"예요."]}, {"say": "Con la Alhambra detrás", "opts": [["with the Alhambra behind", "알람브라가 뒤에 나오게"], ["in front of the Alhambra", "알람브라 앞에서"], ["after the Alhambra", "알람브라 다음에"]], "ans": 0, "why": ["Detrás: behind. Delante: in front.", "detrás는 \"뒤에\", delante는 \"앞에\"예요."]}, {"say": "Otra, por si acaso", "opts": [["another one, just in case", "혹시 모르니 한 장 더요"], ["another one, by accident", "실수로 한 장 더요"], ["no more, thanks", "이제 됐어요, 고마워요"]], "ans": 0, "why": ["Por si acaso: just in case.", "por si acaso는 \"혹시 모르니\"예요."]}, {"say": "¡Qué vista tan bonita!", "opts": [["what a beautiful view!", "정말 멋진 경치다!"], ["what a beautiful visit!", "정말 멋진 방문이다!"], ["what a long day!", "정말 긴 하루다!"]], "ans": 0, "why": ["Vista: view.", "vista는 \"경치\"예요."]}, {"say": "El sol se está poniendo", "opts": [["the sun is setting", "해가 지고 있어요"], ["the sun is rising", "해가 뜨고 있어요"], ["the sun is very strong", "햇볕이 아주 강해요"]], "ans": 0, "why": ["Ponerse el sol: the sun sets. Salir el sol: it rises.", "ponerse el sol은 \"해가 지다\", salir el sol은 \"해가 뜨다\"예요."]}, {"say": "No quiero que se acabe este día", "opts": [["I do not want this day to end", "이 하루가 끝나지 않았으면 좋겠어요"], ["I do not want to start the day", "하루를 시작하기 싫어요"], ["this day was too long", "오늘은 너무 길었어요"]], "ans": 0, "why": ["Se acabe: the form used after no quiero que. Learn it as a set phrase.", "se acabe는 no quiero que 뒤에 쓰는 형태예요. 통째로 익혀요."]}], "speak": [{"w": "¿Nos hace una foto, por favor?", "m": ["could you take a photo of us, please?", "저희 사진 좀 찍어 주실래요?"], "n": ["nos A-theh OO-na FO-to.", "\"노스 아쎄 우나 포또\"."]}, {"w": "Otra, por si acaso", "m": ["another one, just in case", "혹시 모르니 한 장 더요"], "n": ["O-tra, por see a-KA-so.", "\"오뜨라, 뽀르 시 아까소\"."]}, {"w": "¡Qué vista tan bonita!", "m": ["what a beautiful view!", "정말 멋진 경치다!"], "n": ["keh BEES-ta tan bo-NEE-ta.", "\"께 비스따 딴 보니따\"."]}, {"w": "El sol se está poniendo", "m": ["the sun is setting", "해가 지고 있어요"], "n": ["el sol seh es-TA po-NYEN-do.", "\"엘 솔 세 에스따 뽀니엔도\"."]}], "build": [{"s": "¿Me hace una foto, por favor?", "m": ["could you take a photo of me, please?", "제 사진 좀 찍어 주실래요?"]}, {"s": "Con las montañas detrás", "m": ["with the mountains behind", "산이 뒤에 나오게"]}, {"s": "Es la vista más bonita de Granada", "m": ["it is the most beautiful view in Granada", "그라나다에서 가장 아름다운 경치예요"]}, {"s": "Muchas gracias, ha quedado preciosa", "m": ["thank you so much, it came out lovely", "정말 고마워요, 아주 예쁘게 나왔어요"], "why": ["Quedar: to turn out.", "quedar는 \"~하게 되다, 나오다\"예요."]}], "note": ["The Mirador de San Nicolás is in the Albaicín, Granada's old Moorish quarter of white houses and narrow lanes, across the valley from the Alhambra. On clear days, the snowy peaks of the Sierra Nevada rise behind the palace.", "산 니콜라스 전망대는 알람브라 맞은편 골짜기 너머, 하얀 집과 좁은 골목이 이어지는 그라나다의 옛 무어인 지구 알바이신에 있어요. 맑은 날에는 궁전 뒤로 시에라 네바다의 눈 덮인 봉우리가 솟아 있어요."], "today": [0, 2, 3]};
LESSONS8[13] = {"guide": "lucia", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Una paella valenciana para dos", "m": ["a Valencian paella for two", "발렌시아식 파에야 2인분"]}, {"w": "¿Cuánto tarda?", "m": ["how long does it take?", "얼마나 걸려요?"]}, {"w": "Tarda unos veinte minutos", "m": ["it takes about twenty minutes", "20분쯤 걸려요"]}, {"w": "¿Qué lleva la paella valenciana?", "m": ["what is in Valencian paella?", "발렌시아식 파에야에는 뭐가 들어가요?"]}, {"w": "Lleva pollo, conejo y judías verdes", "m": ["it has chicken, rabbit, and green beans", "닭고기, 토끼고기, 껍질콩이 들어가요"]}, {"w": "¡Me encanta el socarrat!", "m": ["I love the crispy bottom!", "눌은 바닥이 정말 좋아요!"], "n": ["Socarrat: the toasted rice at the bottom of the pan.", "socarrat는 팬 바닥에 눌어붙은 바삭한 밥이에요."]}], "intro": ["Valencia is the home of paella. Today you will order the real one, learn what goes in it, and wait patiently, because good paella is made to order.", "발렌시아는 파에야의 고향이에요. 오늘은 진짜 파에야를 주문하고, 뭐가 들어가는지 배우고, 느긋하게 기다려 봐요. 좋은 파에야는 주문을 받고 나서 만들거든요."], "tip": ["Paella is usually ordered for at least two people and cooked fresh, so ¿cuánto tarda? is a good question. Valencian paella has chicken, rabbit, and green beans, while paella de marisco has seafood. Locals eat it at lunch, not at dinner, and often on Sundays with family. The best part, they say, is the socarrat, the crispy rice stuck to the pan.", "파에야는 보통 2인분 이상으로 주문하고 바로 만들기 때문에 ¿cuánto tarda?라고 묻는 게 좋아요. 발렌시아식 파에야에는 닭고기, 토끼고기, 껍질콩이 들어가고, paella de marisco에는 해산물이 들어가요. 이곳 사람들은 저녁이 아니라 점심에 먹고, 일요일에 가족과 함께 먹는 일이 많아요. 가장 맛있는 부분은 팬에 눌어붙은 바삭한 밥, socarrat라고들 해요."], "choose": [{"say": "Una paella valenciana para dos", "opts": [["a Valencian paella for two", "발렌시아식 파에야 2인분"], ["two Valencian paellas", "발렌시아식 파에야 두 개"], ["a paella pan for two", "2인용 파에야 팬"]], "ans": 0, "why": ["Para dos: for two people.", "para dos는 \"2인분\"이에요."]}, {"say": "¿Cuánto tarda?", "opts": [["how long does it take?", "얼마나 걸려요?"], ["how much is it?", "얼마예요?"], ["is it late?", "늦었어요?"]], "ans": 0, "why": ["Tardar: to take time.", "tardar는 \"시간이 걸리다\"예요."]}, {"say": "Tarda unos veinte minutos", "opts": [["it takes about twenty minutes", "20분쯤 걸려요"], ["it costs about twenty euros", "20유로쯤 해요"], ["it is for twenty people", "20인분이에요"]], "ans": 0, "why": ["Unos: about, from Hontanas.", "unos는 온타나스에서 배운 \"~쯤\"이에요."]}, {"say": "¿Qué lleva la paella valenciana?", "opts": [["what is in Valencian paella?", "발렌시아식 파에야에는 뭐가 들어가요?"], ["how big is the paella?", "파에야는 얼마나 커요?"], ["who brings the paella?", "파에야는 누가 가져와요?"]], "ans": 0, "why": ["Llevar: to contain, from Nájera.", "llevar는 나헤라에서 배운 \"들어가 있다\"예요."]}, {"say": "Lleva pollo, conejo y judías verdes", "opts": [["it has chicken, rabbit, and green beans", "닭고기, 토끼고기, 껍질콩이 들어가요"], ["it has fish, shrimp, and peas", "생선, 새우, 완두콩이 들어가요"], ["it has rice and nothing else", "밥만 들어가요"]], "ans": 0, "why": ["Conejo: rabbit. Judías verdes: green beans.", "conejo는 \"토끼\", judías verdes는 \"껍질콩\"이에요."]}, {"say": "¡Me encanta el socarrat!", "opts": [["I love the crispy bottom!", "눌은 바닥이 정말 좋아요!"], ["I love the seafood!", "해산물이 정말 좋아요!"], ["I love the lemon!", "레몬이 정말 좋아요!"]], "ans": 0, "why": ["Socarrat: the crispy rice at the bottom.", "socarrat는 바닥의 바삭한 밥이에요."]}], "speak": [{"w": "Una paella valenciana para dos", "m": ["a Valencian paella for two", "발렌시아식 파에야 2인분"], "n": ["OO-na pa-EH-ya ba-len-THYA-na PA-ra dos.", "\"우나 빠에야 발렌씨아나 빠라 도스\"."]}, {"w": "Tarda unos veinte minutos", "m": ["it takes about twenty minutes", "20분쯤 걸려요"], "n": ["TAR-da OO-nos BEYN-teh mee-NOO-tos.", "\"따르다 우노스 베인떼 미누또스\"."]}, {"w": "¿Qué lleva la paella valenciana?", "m": ["what is in Valencian paella?", "발렌시아식 파에야에는 뭐가 들어가요?"], "n": ["keh YEH-ba la pa-EH-ya ba-len-THYA-na.", "\"께 예바 라 빠에야 발렌씨아나\"."]}, {"w": "Lleva pollo, conejo y judías verdes", "m": ["it has chicken, rabbit, and green beans", "닭고기, 토끼고기, 껍질콩이 들어가요"], "n": ["YEH-ba PO-yo, ko-NEH-ho ee hoo-DEE-as BEHR-des.", "\"예바 뽀요, 꼬네호 이 후디아스 베르데스\"."]}], "build": [{"s": "Una paella de marisco para tres", "m": ["a seafood paella for three", "해산물 파에야 3인분"]}, {"s": "No tenemos prisa", "m": ["we are not in a hurry", "저희 급하지 않아요"], "why": ["Prisa: hurry.", "prisa는 \"서두름\"이에요."]}, {"s": "La paella se come a mediodía", "m": ["paella is eaten at midday", "파에야는 점심에 먹어요"]}, {"s": "Está buenísima, de verdad", "m": ["it is really delicious", "정말 맛있어요, 진짜로"]}], "note": ["Paella takes its name from the wide, shallow pan it is cooked in, the paella. It was born in the rice fields around the Albufera, a large lagoon just south of Valencia, where farmers cooked rice over a wood fire with whatever they had at hand.", "파에야라는 이름은 그것을 요리하는 넓고 얕은 팬, paella에서 왔어요. 발렌시아 바로 남쪽의 큰 석호 알부페라 주변 논에서 생겨났는데, 농부들이 장작불 위에서 손에 있는 재료로 밥을 지어 먹던 데서 시작됐어요."], "today": [0, 1, 2]};
LESSONS8[14] = {"guide": "ramon", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "Quiero alquilar una bici", "m": ["I want to rent a bike", "자전거를 빌리고 싶어요"]}, {"w": "¿Cuánto cuesta por hora?", "m": ["how much is it per hour?", "한 시간에 얼마예요?"]}, {"w": "Por todo el día", "m": ["for the whole day", "하루 종일이요"]}, {"w": "¿Hay que dejar una fianza?", "m": ["do I have to leave a deposit?", "보증금을 내야 해요?"]}, {"w": "¿Me deja un casco?", "m": ["can you lend me a helmet?", "헬멧 빌려주실래요?"]}, {"w": "¿Por dónde se va a la playa?", "m": ["which way to the beach?", "해변은 어느 쪽으로 가요?"]}], "intro": ["Valencia is flat and sunny, with a long green park winding through the city, perfect for a bike. Today you will rent one and ride to the sea.", "발렌시아는 평평하고 햇살이 좋고, 도시를 가로지르는 긴 초록 공원이 있어서 자전거 타기에 딱 좋아요. 오늘은 자전거를 빌려 바다까지 달려 봐요."], "tip": ["Alquilar means to rent. Bici is short for bicicleta, and everyone uses it. Prices go por hora, per hour, or por día, per day. Una fianza is a deposit, often taken from your card. Casco is a helmet. And ¿por dónde se va a...? from Hornillos works in any city.", "alquilar는 \"빌리다\"예요. bici는 bicicleta의 줄임말이고, 다들 이렇게 말해요. 요금은 por hora(시간당)나 por día(하루당)로 매겨요. fianza는 보증금이고, 카드에서 잡아 두는 경우가 많아요. casco는 헬멧이에요. 오르니요스에서 배운 ¿por dónde se va a...?는 어느 도시에서나 통해요."], "choose": [{"say": "Quiero alquilar una bici", "opts": [["I want to rent a bike", "자전거를 빌리고 싶어요"], ["I want to buy a bike", "자전거를 사고 싶어요"], ["I want to fix my bike", "자전거를 고치고 싶어요"]], "ans": 0, "why": ["Alquilar: to rent.", "alquilar는 \"빌리다\"예요."]}, {"say": "¿Cuánto cuesta por hora?", "opts": [["how much is it per hour?", "한 시간에 얼마예요?"], ["how many hours is it open?", "몇 시간 열어요?"], ["what time is it?", "몇 시예요?"]], "ans": 0, "why": ["Por hora: per hour.", "por hora는 \"시간당\"이에요."]}, {"say": "Por todo el día", "opts": [["for the whole day", "하루 종일이요"], ["every day", "매일이요"], ["for half a day", "반나절이요"]], "ans": 0, "why": ["Todo el día: the whole day.", "todo el día는 \"하루 종일\"이에요."]}, {"say": "¿Hay que dejar una fianza?", "opts": [["do I have to leave a deposit?", "보증금을 내야 해요?"], ["do I have to leave my bag?", "가방을 맡겨야 해요?"], ["is there a fine?", "벌금이 있어요?"]], "ans": 0, "why": ["Fianza: deposit.", "fianza는 \"보증금\"이에요."]}, {"say": "¿Me deja un casco?", "opts": [["can you lend me a helmet?", "헬멧 빌려주실래요?"], ["can you leave me alone?", "혼자 있게 해 주실래요?"], ["can I leave my helmet?", "헬멧 두고 가도 돼요?"]], "ans": 0, "why": ["Dejar: to lend. Casco: helmet.", "dejar는 \"빌려주다\", casco는 \"헬멧\"이에요."]}, {"say": "¿Por dónde se va a la playa?", "opts": [["which way to the beach?", "해변은 어느 쪽으로 가요?"], ["is the beach far?", "해변이 멀어요?"], ["is the beach open?", "해변 열었어요?"]], "ans": 0, "why": ["Playa: beach.", "playa는 \"해변\"이에요."]}], "speak": [{"w": "Quiero alquilar una bici", "m": ["I want to rent a bike", "자전거를 빌리고 싶어요"], "n": ["KYEH-ro al-kee-LAR OO-na BEE-thee.", "\"끼에로 알낄라르 우나 비씨\"."]}, {"w": "¿Cuánto cuesta por hora?", "m": ["how much is it per hour?", "한 시간에 얼마예요?"], "n": ["KWAN-to KWES-ta por O-ra.", "\"꾸안또 꾸에스따 뽀르 오라\"."]}, {"w": "¿Hay que dejar una fianza?", "m": ["do I have to leave a deposit?", "보증금을 내야 해요?"], "n": ["eye keh deh-HAR OO-na FYAN-tha.", "\"아이 께 데하르 우나 피안싸\"."]}, {"w": "¿Por dónde se va a la playa?", "m": ["which way to the beach?", "해변은 어느 쪽으로 가요?"], "n": ["por DON-deh seh ba a la PLA-ya.", "\"뽀르 돈데 세 바 아 라 쁠라야\"."]}], "build": [{"s": "Quería alquilar dos bicis", "m": ["I would like to rent two bikes", "자전거 두 대 빌리고 싶어요"]}, {"s": "¿Cuánto cuesta por día?", "m": ["how much is it per day?", "하루에 얼마예요?"]}, {"s": "La playa está a veinte minutos en bici", "m": ["the beach is twenty minutes by bike", "해변은 자전거로 20분이에요"], "why": ["En bici: by bike.", "en bici는 \"자전거로\"예요."]}, {"s": "Devuelvo la bici a las seis", "m": ["I return the bike at six", "여섯 시에 자전거를 반납해요"]}], "note": ["After a terrible flood in 1957, Valencia moved its river, the Turia, away from the city. The old dry riverbed became the Jardín del Turia, a green park about nine kilometers long, with paths, sports fields, and bridges overhead. At its end stands the futuristic City of Arts and Sciences.", "1957년의 끔찍한 홍수 뒤, 발렌시아는 투리아강의 물길을 도시 밖으로 돌렸어요. 말라 버린 옛 강바닥은 약 9킬로미터에 이르는 초록 공원, 투리아 정원이 되었어요. 산책로와 운동장이 있고, 머리 위로 다리들이 지나가요. 공원 끝에는 미래 도시 같은 예술과 과학의 도시가 서 있어요."], "today": [0, 1, 3]};
LESSONS8[15] = {"guide": "begona", "chooseTitle": ["Pick the meaning", "뜻 고르기"], "chooseHint": ["Listen, then pick what it means.", "듣고 무슨 뜻인지 골라요."], "phrases": [{"w": "El tren lleva retraso", "m": ["the train is delayed", "기차가 지연되고 있어요"]}, {"w": "¿Cuánto retraso lleva?", "m": ["how late is it?", "얼마나 늦어요?"]}, {"w": "El tren está cancelado", "m": ["the train is cancelled", "기차가 취소됐어요"]}, {"w": "¿Qué puedo hacer?", "m": ["what can I do?", "어떻게 하면 돼요?"]}, {"w": "¿Me pueden cambiar el billete?", "m": ["can you change my ticket?", "표를 바꿔 주실 수 있어요?"]}, {"w": "Quiero poner una reclamación", "m": ["I want to make a complaint", "민원을 넣고 싶어요"], "n": ["Una reclamación: a formal complaint.", "reclamación은 공식적인 민원이에요."]}], "intro": ["The last lesson. On your way back from Valencia, the screen at the station shows a delay. Today you will deal calmly with a travel problem, using everything you have learned, from no pasa nada to ¿me puede ayudar?", "마지막 과예요. 발렌시아에서 돌아가는 길, 역 전광판에 지연 표시가 떴어요. 오늘은 no pasa nada부터 ¿me puede ayudar?까지 배운 걸 모두 써서 여행 중의 문제를 차분하게 해결해 봐요."], "tip": ["Retraso is a delay, and llevar retraso means to be running late: el tren lleva retraso, lleva veinte minutos de retraso. Cancelado is cancelled. At the ticket office, ask ¿qué puedo hacer? and ¿me pueden cambiar el billete? If you want to complain formally, ask for the hoja de reclamaciones, the complaints form every business in Spain must have. And when it is solved: no pasa nada.", "retraso는 \"지연\"이고, llevar retraso는 \"늦어지고 있다\"예요. el tren lleva retraso, lleva veinte minutos de retraso. cancelado는 \"취소된\"이에요. 매표소에서는 ¿qué puedo hacer?와 ¿me pueden cambiar el billete?라고 물어요. 정식으로 항의하고 싶으면 hoja de reclamaciones(민원서)를 달라고 해요. 스페인의 모든 업체는 이것을 갖추고 있어야 해요. 해결되면 no pasa nada."], "choose": [{"say": "El tren lleva retraso", "opts": [["the train is delayed", "기차가 지연되고 있어요"], ["the train is early", "기차가 일찍 왔어요"], ["the train is full", "기차가 꽉 찼어요"]], "ans": 0, "why": ["Retraso: delay.", "retraso는 \"지연\"이에요."]}, {"say": "¿Cuánto retraso lleva?", "opts": [["how late is it?", "얼마나 늦어요?"], ["how much does it cost?", "얼마예요?"], ["how long is the trip?", "여행은 얼마나 걸려요?"]], "ans": 0, "why": ["Llevar retraso: to be running late.", "llevar retraso는 \"늦어지고 있다\"예요."]}, {"say": "El tren está cancelado", "opts": [["the train is cancelled", "기차가 취소됐어요"], ["the train is closed", "기차가 닫혔어요"], ["the train is tired", "기차가 지쳤어요"]], "ans": 0, "why": ["Cancelado: cancelled.", "cancelado는 \"취소된\"이에요."]}, {"say": "¿Qué puedo hacer?", "opts": [["what can I do?", "어떻게 하면 돼요?"], ["what are you doing?", "뭐 하세요?"], ["can I do it?", "해도 돼요?"]], "ans": 0, "why": ["Puedo: I can. Hacer: to do.", "puedo는 \"할 수 있다\", hacer는 \"하다\"예요."]}, {"say": "¿Me pueden cambiar el billete?", "opts": [["can you change my ticket?", "표를 바꿔 주실 수 있어요?"], ["can you give me change?", "잔돈 주실 수 있어요?"], ["can I buy a ticket?", "표 살 수 있어요?"]], "ans": 0, "why": ["Cambiar: to change.", "cambiar는 \"바꾸다\"예요."]}, {"say": "Quiero poner una reclamación", "opts": [["I want to make a complaint", "민원을 넣고 싶어요"], ["I want to make a reservation", "예약하고 싶어요"], ["I want to claim my bag", "가방을 찾고 싶어요"]], "ans": 0, "why": ["Reclamación: complaint.", "reclamación은 \"민원\"이에요."]}], "speak": [{"w": "El tren lleva retraso", "m": ["the train is delayed", "기차가 지연되고 있어요"], "n": ["el tren YEH-ba rreh-TRA-so.", "\"엘 뜨렌 예바 레뜨라소\"."]}, {"w": "El tren está cancelado", "m": ["the train is cancelled", "기차가 취소됐어요"], "n": ["el tren es-TA kan-theh-LA-do.", "\"엘 뜨렌 에스따 깐쎌라도\"."]}, {"w": "¿Qué puedo hacer?", "m": ["what can I do?", "어떻게 하면 돼요?"], "n": ["keh PWEH-do a-THEHR.", "\"께 뿌에도 아쎄르\"."]}, {"w": "¿Me pueden cambiar el billete?", "m": ["can you change my ticket?", "표를 바꿔 주실 수 있어요?"], "n": ["meh PWEH-den kam-BYAR el bee-YEH-teh.", "\"메 뿌에덴 깜비아르 엘 비예떼\"."]}], "build": [{"s": "El tren lleva media hora de retraso", "m": ["the train is half an hour late", "기차가 30분 늦어지고 있어요"]}, {"s": "Perdone, ¿me puede ayudar?", "m": ["excuse me, can you help me?", "실례합니다, 도와주실 수 있어요?"]}, {"s": "Quería cambiar el billete para mañana", "m": ["I would like to change the ticket to tomorrow", "표를 내일 걸로 바꾸고 싶어요"]}, {"s": "Vale, no pasa nada, gracias", "m": ["okay, no problem, thanks", "알겠어요, 괜찮아요, 고마워요"]}], "note": ["Valencia's famous festival, the Fallas, fills the city every March with giant figures of wood and paper, some as tall as buildings, which are burned on the last night. You have finished the train trips and the whole site. From the Pyrenees to the Atlantic, and across Spain by train: ¡enhorabuena, y buen viaje!", "발렌시아의 유명한 축제 파야스(Fallas)는 매년 3월, 건물만큼 큰 것도 있는 나무와 종이로 만든 거대한 인형들로 도시를 가득 채우고, 마지막 밤에 그것들을 태워요. 기차 여행도, 이 사이트 전체도 다 마쳤어요. 피레네에서 대서양까지, 그리고 기차로 스페인 곳곳을. ¡enhorabuena, y buen viaje!(축하해요, 좋은 여행 되세요!)"], "today": [0, 2, 3], "final": true};
